changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne – Bundesrat et gouvernements des Länder', 'Les membres du Bundesrat (catégorie DE-b) et ministres-présidents et ministres des 16 Länder (catégorie DE-a), d’après bundesrat.de', 'de_pep_bundesrat', 'PEP', 'https://www.bundesrat.de', 'de-pep-bundesrat', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-bundesrat-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"url": "https://www.bundesrat.de/DE/bundesrat/mitglieder/mitglieder-node.html?param3=Alle"}', 24, 12, 'Citer la source (Bundesrat)', 'Bundesrat, www.bundesrat.de', 'Extrait les membres titulaires et suppléants du Bundesrat, qui composent les exécutifs des 16 Länder. Donne d’un coup les ministres-présidents et ministres régionaux.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les membres titulaires du Bundesrat avec leur Land et leur parti.', 'Les anciens membres ne sont pas repris sur la page courante.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-b' AND f.label LIKE 'Membre du Bundesrat%' AND f.label NOT LIKE '%suppléant%' AND p.dataset_name = 'de_pep_bundesrat';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les membres suppléants du Bundesrat avec leur Land et leur parti.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-b' AND f.label LIKE 'Membre suppléant du Bundesrat%' AND p.dataset_name = 'de_pep_bundesrat';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les ministres-présidents et maires gouverneurs des 16 Länder, avec leur fonction régionale exacte.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Ministre-président d''un Land%' AND p.dataset_name = 'de_pep_bundesrat';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les ministres et sénateurs des 16 Länder siégeant au Bundesrat.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Ministre ou sénateur d''un gouvernement de Land%' AND p.dataset_name = 'de_pep_bundesrat';

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne – Gouvernement fédéral', 'Chancelier fédéral et ministres fédéraux, d’après bundesregierung.de (catégorie DE-a)', 'de_pep_federal_government', 'PEP', 'https://www.bundesregierung.de/breg-de/bundesregierung/bundeskabinett', 'de-pep-federal-government', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-federal-government-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"url": "https://www.bundesregierung.de/breg-de/bundesregierung/bundeskabinett"}', 24, 12, 'Citer la source (Presse- und Informationsamt der Bundesregierung)', 'Presse- und Informationsamt der Bundesregierung, www.bundesregierung.de', 'Lit la page officielle du cabinet fédéral. Donne le Chancelier et les ministres fédéraux avec leur fonction exacte et portrait officiel.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Le Chancelier fédéral avec son portrait officiel.', 'Les anciens membres ne sont pas repris sur la page courante.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Chancelier fédéral%' AND p.dataset_name = 'de_pep_federal_government';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les ministres fédéraux et ministres d''État du cabinet.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Ministre fédéral ou ministre d''État%' AND p.dataset_name = 'de_pep_federal_government';
